(function(){
'use strict';
const KEY='central-v6:pt:m9:v1';
let state={};try{state=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch(_){state={}}
state.read=state.read||{};state.activeSession=state.activeSession||'s1';
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){console.warn('[PT M9 save]',e)}updateProgress();notifyResize()}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function notifyResize(){try{if(window.parent&&window.frameElement&&window.parent.PtM6V1&&typeof window.parent.PtM6V1.resize==='function')window.parent.PtM6V1.resize(window.frameElement)}catch(_){}}
function renderTheory(){const host=document.getElementById('m9Theory');if(!host||!Array.isArray(window.PT_M9_SESSIONS))return;host.innerHTML=window.PT_M9_SESSIONS.map((s,i)=>'<details class="session" data-session="'+esc(s.id)+'" '+(state.activeSession===s.id?'open':'')+'><summary><span class="session-no">'+String(i+1).padStart(2,'0')+'</span><span>'+esc(s.title)+'</span></summary><div class="body">'+s.html+'<label class="check"><input type="checkbox" data-read="'+esc(s.id)+'"> <span>Li e entendi esta sessão</span></label></div></details>').join('');host.querySelectorAll('.session').forEach(d=>d.addEventListener('toggle',()=>{if(d.open){state.activeSession=d.dataset.session;try{localStorage.setItem(KEY,JSON.stringify(state))}catch(_){}setTimeout(notifyResize,40)}}));host.querySelectorAll('[data-read]').forEach(b=>{b.checked=!!state.read[b.dataset.read];b.addEventListener('change',()=>{state.read[b.dataset.read]=b.checked;save()})});updateProgress();setTimeout(notifyResize,80)}
function updateProgress(){const total=Array.isArray(window.PT_M9_SESSIONS)?window.PT_M9_SESSIONS.length:8;const done=Object.keys(state.read).filter(k=>state.read[k]).length;const pct=total?Math.round(done/total*100):0;const p=document.getElementById('pct'),bar=document.getElementById('bar'),c=document.getElementById('readCount');if(p)p.textContent=pct+'%';if(bar)bar.style.width=pct+'%';if(c)c.textContent=done+' de '+total+' sessões'}
function parentWindow(){try{return window.parent&&window.parent!==window?window.parent:null}catch(_){return null}}
function tecData(){const p=parentWindow();try{const data=p&&p.TEC_CADERNOS_DATA;return data&&Array.isArray(data.cadernos)?data.cadernos:[]}catch(_){return []}}
function resolveTec(){const list=tecData();return list.find(c=>String(c.id)==='port-11')||list.find(c=>/orações coordenadas e subordinadas|oracoes coordenadas e subordinadas/i.test(String(c.nome||'')))||null}
function renderTec(){const host=document.getElementById('m9Tec');if(!host)return;const c=resolveTec();if(c){const qtd=Number(c.questoes)||0;host.innerHTML='<div class="tec-card"><div><span class="eyebrow">Caderno localizado na Central</span><h2>PORT 11 — '+esc(String(c.nome||'Orações coordenadas e subordinadas').replace(/^PORT\s*11\s*-\s*/i,''))+'</h2><p>'+(qtd?esc(new Intl.NumberFormat('pt-BR').format(qtd))+' questões no caderno já cadastrado. ':'')+'O endereço é reutilizado da própria Central; nenhum link novo foi criado.</p></div><button class="tec-open" id="m9OpenTec">Abrir questões no TEC ↗</button></div><div class="tec-guide"><b>Ordem sugerida de treino</b><p>Arquitetura do período → coordenação → substantivas → adjetivas → adverbiais → reduzidas/paralelismo → QUE/SE/COMO em contexto.</p></div>';const btn=document.getElementById('m9OpenTec');if(btn)btn.onclick=openTec}else{host.innerHTML='<div class="tec-card"><div><span class="eyebrow">Questões</span><h2>PORT 11 — Orações coordenadas e subordinadas</h2><p>Abra este módulo pela Central para que o caderno já cadastrado seja localizado automaticamente.</p></div><button class="tec-open" id="m9OpenTec">Abrir Cadernos TEC</button></div>';const btn=document.getElementById('m9OpenTec');if(btn)btn.onclick=openTec}notifyResize()}
function openTec(){const p=parentWindow(),c=resolveTec();try{if(c&&c.url){if(p&&typeof p.tecAbrirCaderno==='function'){p.tecAbrirCaderno(c.url);return false}window.open(c.url,'_blank','noopener');return false}if(p&&typeof p.tecAbrirListaContexto==='function'){p.tecAbrirListaContexto('Língua Portuguesa','orações coordenadas');return false}if(p&&typeof p.centralSidebarAction==='function'){p.centralSidebarAction('tec-cadernos');setTimeout(()=>{try{const q=p.document.getElementById('tecBusca');if(q){q.value='orações coordenadas';if(typeof p.tecCadernosRender==='function')p.tecCadernosRender()}}catch(_){}},120);return false}}catch(e){console.warn('[PT M9 TEC]',e)}alert('Abra “Cadernos TEC” na Central e pesquise por PORT 11.');return false}
function bindTabs(){document.querySelectorAll('.tab').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));btn.classList.add('active');const panel=document.getElementById(btn.dataset.tab);if(panel)panel.classList.add('active');if(btn.dataset.tab==='tec')renderTec();setTimeout(notifyResize,50)}))}
window.PtM9Runtime={openTec,renderTec};renderTheory();renderTec();bindTabs();updateProgress();setTimeout(renderTec,500);setTimeout(renderTec,1500);
})();
